// SidebarHeroNews (overlay sidebar) banne aa j function vapare che.
export function getFillerArticles() {
  const all = [];
  Object.values(articles).forEach((list) => {
    (list || []).forEach((item) => {
      if (item?.isFiller) all.push(item);
    });
  });
  return all;
}